import React from 'react';

const Projects = () => {
  const projects = [
    {
      id: 1,
      title: 'Heritage Coffee Brand',
      category: 'Brand Identity',
      year: '2024',
    },
    {
      id: 2,
      title: 'Modern Architecture Magazine',
      category: 'Editorial Design',
      year: '2024',
    },
    {
      id: 3,
      title: 'Vintage Records Co.',
      category: 'Packaging Design',
      year: '2023',
    },
    {
      id: 4,
      title: 'Botanical Gardens Identity',
      category: 'Brand Identity',
      year: '2023',
    },
    {
      id: 5,
      title: 'Artisan Bakery',
      category: 'Brand Identity',
      year: '2023',
    },
    {
      id: 6,
      title: 'Tech Conference Materials',
      category: 'Print Design',
      year: '2022',
    },
    {
      id: 7,
      title: 'Luxury Watch Campaign',
      category: 'Advertising',
      year: '2022',
    },
    {
      id: 8,
      title: 'Sustainable Fashion Brand',
      category: 'Brand Identity',
      year: '2022',
    },
    {
      id: 9,
      title: 'Cultural Festival',
      category: 'Event Design',
      year: '2021',
    },
  ];

  const categories = ['All', 'Brand Identity', 'Editorial Design', 'Packaging Design', 'Print Design', 'Advertising', 'Event Design'];

  return (
    <div className="section" style={{ paddingTop: '120px' }}>
      <div className="container">
        {/* Header */}
        <div className="section-header">
          <p className="section-label">Portfolio</p>
          <h1>Projects</h1>
        </div>

        {/* Filter */}
        <div
          style={{
            display: 'flex',
            gap: 'var(--space-6)',
            marginBottom: 'var(--space-12)',
            flexWrap: 'wrap',
          }}
        >
          {categories.map((category, index) => (
            <button
              key={index}
              className="text-mono"
              style={{
                background: 'none',
                border: 'none',
                padding: 'var(--space-2) 0',
                cursor: 'pointer',
                color: index === 0 ? 'var(--color-accent)' : 'var(--color-gray)',
                borderBottom: index === 0 ? '2px solid var(--color-accent)' : '2px solid transparent',
                transition: 'all var(--transition-fast)',
              }}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Projects Grid */}
        <div className="project-grid">
          {projects.map((project) => (
            <article key={project.id} className="project-card">
              <div className="project-card-image">
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    backgroundColor: 'var(--color-cream-dark)',
                    fontFamily: 'var(--font-mono)',
                    fontSize: 'var(--text-xs)',
                    color: 'var(--color-gray-light)',
                  }}
                >
                  {project.category}
                </div>
              </div>
              <div className="project-card-content">
                <span className="project-card-category">
                  {project.category} — {project.year}
                </span>
                <h3 className="project-card-title">{project.title}</h3>
              </div>
            </article>
          ))}
        </div>

        {/* Decorative Line */}
        <div className="decorative-line" style={{ margin: 'var(--space-16) 0' }} ></div>

        {/* Collaboration CTA */}
        <div className="text-center">
          <p
            className="text-mono"
            style={{ color: 'var(--color-gray-light)', marginBottom: 'var(--space-4)' }}
          >
            Interested in collaborating?
          </p>
          <a
            href="mailto:hello@portfolio.com"
            style={{
              fontSize: 'var(--text-2xl)',
              fontWeight: 700,
              color: 'var(--color-black)',
            }}
          >
            hello@portfolio.com
          </a>
        </div>
      </div>
    </div>
  );
};

export default Projects;
